def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    last_my, last_opp = history[-1]

    opp_d = 0
    for _, o in history:
        if o == 'D':
            opp_d += 1

    W = n if n < 18 else 18
    start = n - W
    r_d = 0
    for i in range(start, n):
        if history[i][1] == 'D':
            r_d += 1
    r_c = W - r_d

    forgive = punish = 0
    for i in range(1, n):
        pm = history[i - 1][0]
        if pm == 'D':
            if history[i][1] == 'C':
                forgive += 1
            else:
                punish += 1

    recent_trans = n - 1
    if recent_trans > 15:
        recent_trans = 15
    rf = rp = 0
    for i in range(n - recent_trans, n):
        if i <= 0:
            continue
        pm = history[i - 1][0]
        if pm == 'D':
            if history[i][1] == 'C':
                rf += 1
            else:
                rp += 1

    total_tol = forgive - punish
    recent_tol = rf - rp

    if W <= 5:
        stable_coop = r_d <= 1
    else:
        stable_coop = r_d <= max(2, W // 4)

    tolerant = False
    if opp_d == 0 and forgive >= 1 and punish == 0:
        tolerant = True
    if stable_coop and recent_tol >= 1:
        tolerant = True
    if total_tol >= 3 and recent_tol >= 0:
        tolerant = True
    if recent_tol >= 2 and r_c >= W - 2:
        tolerant = True

    if last_opp == 'D':
        streak = 0
        for i in range(n - 1, -1, -1):
            if history[i][1] == 'D':
                streak += 1
            else:
                break

        streak_start = n - streak
        provoked_streak = streak_start > 0 and history[streak_start - 1][0] == 'D'

        if provoked_streak:
            if streak >= 5 or opp_d * 3 >= n * 2:
                return 'D'
            if recent_tol > 0 and streak <= 1 and stable_coop:
                return 'D'
            if total_tol >= 3 and streak <= 1 and stable_coop:
                return 'D'
            return 'C'

        if opp_d * 3 >= n * 2 or (W >= 6 and r_d * 4 >= W * 3):
            return 'D'
        return 'D'

    if opp_d * 4 >= n * 3 or (W >= 6 and r_d * 4 >= W * 3):
        return 'D'

    if tolerant:
        return 'D'

    if last_my == 'C':
        if opp_d == 0 and n == 8:
            return 'D'

        if n == 30 and total_tol == 0 and stable_coop and opp_d <= max(1, n // 8):
            return 'D'

        if stable_coop and opp_d <= max(2, n // 5) and total_tol >= 0 and 15 <= n <= 85:
            if rng.random() < 0.012:
                return 'D'

        return 'C'

    return 'C'
